import{_ as n,o,c as r,a3 as e}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"Planning-Oriented End-to-End Autonomous Driving: Architectures, Evaluation, and Emerging Paradigms","description":"","frontmatter":{"title":"Planning-Oriented End-to-End Autonomous Driving: Architectures, Evaluation, and Emerging Paradigms","arxiv":"2608.20111","date":"2026-08-20","authors":"Yanchen Guan, Xingcheng Liu, Bin Rao, Chengyue Wang, Guofa Li, Yunjian Li, Lishengsa Yue, Zhiyong Cui, Chengzhong Xu, Zhenning Li","categories":"cs.RO, cs.ET","topics":"端到端自动驾驶, 规划评测协议, 综述","outline":[2,2]},"headers":[],"relativePath":"papers/2608.20111.md","filePath":"papers/2608.20111.md","lastUpdated":null}'),a={name:"papers/2608.20111.md"};function s(i,t,g,l,u,d){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="planning-oriented-end-to-end-autonomous-driving-architectures-evaluation-and-emerging-paradigms" tabindex="-1">Planning-Oriented End-to-End Autonomous Driving: Architectures, Evaluation, and Emerging Paradigms <a class="header-anchor" href="#planning-oriented-end-to-end-autonomous-driving-architectures-evaluation-and-emerging-paradigms" aria-label="Permalink to &quot;Planning-Oriented End-to-End Autonomous Driving: Architectures, Evaluation, and Emerging Paradigms&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2608.20111" target="_blank" rel="noreferrer">2608.20111</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-08-20</td></tr><tr><td><strong>作者</strong></td><td>Yanchen Guan, Xingcheng Liu, Bin Rao, Chengyue Wang, Guofa Li, Yunjian Li, Lishengsa Yue, Zhiyong Cui, Chengzhong Xu, Zhenning Li（澳门大学等）</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.ET</td></tr><tr><td><strong>一句话</strong></td><td>提出&quot;面向规划的端到端&quot;这一重新划界，沿输入表示 / 规划输出 / 监督信号 / 评测协议四轴重组文献，并论证开环位移类指标不足以支撑安全与人类对齐的驾驶主张。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/vla">视觉语言动作模型 VLA</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>自动驾驶传统上是模块化流水线：感知、预测、规划、控制各自为政。好处是每个模块目标清晰、失效面相对可解释，坏处是接口很脆：感知优化的检测指标与规划关系很弱，预测产出的未来下游未必用得上，规划器拿到的是延迟且离散化的抽象。端到端自动驾驶（E2E-AD）正是针对这个<strong>接口问题</strong>出现的。</p><p>但论文指出，&quot;端到端&quot;这个词已经被用滥了。最窄的含义是相机直接回归到方向盘（PilotNet 那一支）。而当代有影响力的方法几乎都保留了结构化中间表示：BEV 特征、向量化场景 token、占据栅格、object query、world model latent、路线编码、语言 token、安全过滤器。<strong>这些系统不是因为去掉了结构才叫端到端，而是因为它们的表示、训练目标与规划头都围绕最终驾驶行为耦合在一起。</strong></p><p>于是作者提出改用 <strong>planning-oriented end-to-end driving</strong> 这个说法，并给出全文中心论点：现代端到端驾驶的关键区分<strong>不在于是否使用中间表示，而在于这些表示是否被学习、被监督、被评测以支撑安全、可行、符合路线的规划</strong>。</p><p>为什么现在做这件事：第一，问题已经从模仿学习能不能压住车道，变成策略在长时程、分布偏移、交互式车流、罕见但安全关键场景下如何表现；第二，<strong>基准设计本身已成为方法论问题</strong>——开环位移误差好复现，却测不出路线进展、碰撞规避、规则遵守与从自身失误中恢复的能力；第三，world model 与 VLA 正在改变规划的含义本身。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>论文用 Table I 明确了自己与已有综述的差别，态度是&quot;不是因为没人总结过，而是因为三件事已经不可分割：模型架构、评测协议、以及新兴的基础模型范式&quot;。</p><p><strong>宽口径 E2E-AD 综述</strong>覆盖动机、架构、数据集与挑战，但对 2024 年之后 NAVSIM / Bench2Drive / WOD-E2E 之间的<strong>协议错配与跨协议相关性</strong>着墨不足。<strong>视觉语言驾驶综述</strong>聚焦 VLM/VLA 的感知、推理、指令遵循与数据生成，却较少追问<strong>语言到底改善了闭环规划还是只改善了 QA 与解释</strong>。</p><p><strong>world model 综述</strong>关心生成预测、场景演化、仿真与潜动力学，但生成得逼真与能据此挑出安全轨迹是两件事。<strong>基础模型综述</strong>讨论大模型在感知、仿真、推理、决策中的角色，缺的是规划专属的基准证据与部署约束。<strong>基准与数据集综述</strong>盘点规模、模态、标注与任务定义，缺的是方法分类学，以及<strong>指标选择如何改变端到端主张的含义</strong>。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>先看一条历史事实：ALVINN 已经证明神经网络能把道路图像映到转向；DeepDriving 引入 affordance 作为中间表示；PilotNet 成为相机到转向的现代参照点。直接行为克隆（BC）的第一个硬伤是<strong>可控性</strong>——同一幅画面在&quot;直行/左转/右转&quot;下需要不同动作，条件模仿学习（CIL）用高层指令条件化解决了这个歧义。</p><p>第二个硬伤没被 CIL 解决：<strong>分布偏移</strong>。策略一旦偏离专家行为就进入训练数据里罕见的状态，误差累积成偏离路线或碰撞。NoCrash 把这个失效模式摆到台面上，ChauffeurNet 用合成扰动与辅助损失回应，其中的教训是——<strong>鲁棒性不只取决于网络设计，还取决于恢复状态如何在训练中被表示</strong>。</p><p>第三步是监督设计的多样化：Learning by Cheating 训一个有特权状态的教师再蒸馏给图像学生；Learning by Watching 从观察到的非自车 agent 提取监督；Learning From All Vehicles 用所有可见车辆的轨迹。这些工作反复指向同一条：<strong>端到端驾驶的性能取决于监督设计的程度不亚于网络架构</strong>。</p><p>顺着这条线往下，作者意识到一个更基础的问题：如果架构、监督、评测三者纠缠，那么单看架构分类学根本无法判断两个方法是不是在解同一个问题。一个用特权蒸馏训练的 BEV 规划器与一个用语言-动作对齐训练的 VLA 规划器，即使都用 transformer 也不属于同一个规划族。于是需要一套<strong>沿变量而非沿骨干</strong>的分类学。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>端到端不是&quot;没有结构&quot;，而是&quot;结构被规划目标拉着长&quot;。判断一个驾驶系统该不该被相信，看的不是它的骨干名字，而是四件事：<strong>哪些驾驶变量被暴露给策略、策略在什么输出空间里优化、什么监督让这个输出可学、以及哪种评测协议支撑了它的主张</strong>。而其中最容易造成误判的是最后一轴——开环位移误差便宜好复现，但它在专家状态分布下打分，而部署时策略要面对<strong>自己诱导出来的</strong>状态分布。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>综述的&quot;方法&quot;是它的检索与组织流程，论文把它写得相当可审计。</p><p><strong>检索协议</strong>（Fig. 1）：结构化叙述性综述，来源包括 IEEE Xplore、ACM DL、SpringerLink、ScienceDirect、arXiv、OpenReview、CVF Open Access、NeurIPS proceedings、公开基准仓库与官方项目页。检索期主要覆盖 <strong>2015 年至 2026 年 6 月</strong>，更早的工作在塑造了神经/端到端驾驶时纳入。核心检索词包括 end-to-end autonomous driving、learning-based planning、closed-loop driving、nuPlan、NAVSIM、Bench2Drive、WOD-E2E、world model autonomous driving、VLA driving、long-tail autonomous driving 等。此外从高连通节点做前向与后向引文追踪，锚点包括 PilotNet、CIL、Learning by Cheating、TransFuser、TCP、UniAD、VAD、NAVSIM、Bench2Drive、DriveLM、SimLingo、WOD-E2E、LEAD。</p><p><strong>纳入/排除标准</strong>：满足以下任一即纳入——提出有影响力的 E2E 驾驶形式化；预测规划相关输出（控制、waypoint、轨迹、轨迹分布、action token）；提出规划评测的基准/数据集/仿真器/指标；贡献与自车规划相关的 world model、VLM 或 VLA 机制；发布公开可复现资源；或提供安全、可解释性、鲁棒性、评测方面的批评。只做感知/检测/分割/跟踪/运动预测的工作被排除，除非它直接支撑自车规划；技术细节不足以比较的纯专有系统同样排除。</p><p><strong>四轴分类学</strong>（Table II）：</p><ul><li><strong>输入表示</strong>：前视图像 / 多视图 / LiDAR-radar 融合 / BEV 或占据 / object-vector token / 潜世界状态 / VLM-VLA token 空间。规划含义：决定几何、交互建模、地图使用，以及策略能否对未见或罕见 agent 做推理。</li><li><strong>输出空间</strong>：转向油门 / waypoint / 轨迹 / 多模态轨迹分布 / 场景 rollout / 语言条件动作 token。决定可控性、不确定性表示、对控制器的依赖，以及<strong>与哪些指标兼容</strong>。</li><li><strong>监督信号</strong>：人类 BC / 合成扰动 / 特权教师 / 规则或 RL 专家 / 辅助感知预测 / world model 预测 / 语言 QA / rater 偏好。决定策略是否学到恢复、安全裕度、语义意图与长尾偏好。</li><li><strong>评测协议</strong>：开环日志回放 / 非反应式仿真 / 反应式闭环仿真 / 真实闭环 / 长尾与偏好感知评测 / 跨基准相关性。决定所报告的主张究竟是关于模仿保真度、可扩展的代理规划、交互、泛化，还是人类对齐判断。</li></ul><p>一个具体的用法示例：论文强调 Table III 里的&quot;limited&quot;标签只表示证据主要是开环、非反应式或受基准约束，<strong>不是对真实部署能力的判断</strong>；公开资源标签也分成 Code / Partial / Benchmark / Paper-only 四级，状态截至 2026 年 6 月。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>综述没有自己的实验，它做的是<strong>对证据体系本身的分析</strong>，最有信息量的部分集中在第 VII 节。</p><p><strong>指标族被明确分层</strong>。开环指标包括 ADE、FDE、轨迹 L2 误差与日志场景上的碰撞代理，作者判断是适合快速迭代、作为最终证据则很弱：模型可能匹配了日志轨迹却无法从偏离中恢复。闭环侧，CARLA Leaderboard 与 Bench2Drive 报 driving score、route completion、违规惩罚、成功率、效率与舒适度；nuPlan 综合安全、进展、可行驶区域合规、TTC、舒适与交通规则；NAVSIM 的 PDMS 在<strong>非反应式真日志</strong>设定下评估规划轨迹；WOD-E2E 的 Rater Feedback Score 度量与 rater 偏好轨迹标签的对齐程度。</p><p><strong>开环与闭环为何系统性地不一致</strong>（第 VII-C 节，全文最有价值的论证之一），论文给了四条结构性原因：其一，开环在<strong>专家的状态分布</strong>下打分，闭环在<strong>策略自己诱导的状态分布</strong>下打分；其二，开环指标会惩罚有效的替代方案，在多模态交互里尤其明显；其三，开环通常缺少背景 agent 反馈与规则违规反馈；其四，闭环结果依赖控制器细节、仿真器动力学与随机场景结果，这些在开环日志里根本不出现。</p><p>作者由此给出一个写作层面的结论：<strong>不指明协议就不该称 SOTA</strong>。强 nuScenes L2、强 NAVSIM PDMS、强 Bench2Drive Driving Score 是三个不同的主张。论文还引用了跨基准相关性工作：安全感知的开环分数与闭环 driving score 的相关性好于 ADE/FDE，但<strong>排名倒置仍然存在，子指标会饱和</strong>。因此可靠的经验主张应当至少在&quot;一个真日志代理协议 + 一个反应式闭环协议&quot;上三角互证。</p><p><strong>推荐的报告协议</strong>（VII-D）：报告五组证据——开环轨迹质量、非反应式真日志规划分数、闭环路线与违规指标、长尾或偏好感知表现、定性失效分析；并披露传感器配置、输出类型、控制器、安全包装、数据过滤、算力预算、随机种子与基准版本。论文建议<strong>放弃“最佳方法”单列</strong>，理由是“比较的单位应该是主张，不是模型名字”。</p><p><strong>关于 VLA 驾驶的判断</strong>（VI-B）值得单列。论文承认语言正在从“标注”走向“动作脚手架”（SimLingo 的语言-动作对齐、ORION 的视觉语言指令动作生成、SpaceDrive 的空间 token、WAM-Flow 的结构化 action token 离散流匹配），但强调三种角色的算力、安全与验证含义完全不同：<strong>训练时的语言、在线规划时的语言、事后解释的语言</strong>。判据很硬：关键证据不是语言合理性、解释质量或 VQA 准确率，而是<strong>语言 grounding 是否改善了轨迹选择、恢复行为、可控性与长尾决策质量</strong>。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：当代端到端驾驶保留了大量结构化中间表示，所以&quot;是否端到端&quot;应该改问&quot;结构是否被学习、被监督、被评测以服务于规划&quot;。据此论文沿输入表示、规划输出、监督信号、评测协议四轴重组文献，避免按骨干名字分类造成的误判。评测是最容易出问题的一轴：开环在专家状态分布下打分，闭环在策略自诱导分布下打分，两者不一致有结构性原因，排名倒置真实存在。论文因此建议按协议分列报告、放弃单一&quot;最佳方法&quot;列，并把算力当作一等科学变量。对 VLA 驾驶，判据是语言是否改善了轨迹与恢复行为，而不是解释质量或 VQA 准确率。</p><p><strong>3 句话版</strong>：端到端不等于无结构，判断标准应是结构、监督、评测是否共同支撑安全可行的规划。开环位移指标只是诊断量，不构成驾驶能力的证据。跨协议相关性、长尾与偏好感知评测、以及算力归一化比较，是这个领域下一阶段的方法论功课。</p><p><strong>1 句话版</strong>：别问一个驾驶模型有多&quot;端到端&quot;，问它的评测协议支撑得起什么主张。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>这是一篇综述，它最脆弱的地方不在方法而在<strong>它自己的中心论断能否被它自己的证据支撑</strong>。全文的规范性结论是&quot;应当跨协议三角互证&quot;，而支撑这一结论的关键实证是一处引用：跨参照 NAVSIM 与 Bench2Drive 的相关性研究提示安全感知开环分数与闭环 driving score 的相关性优于 ADE/FDE，但仍有排名倒置与子指标饱和。<strong>论文本身没有做任何原创的跨协议测量</strong>——它在 IX-C 里把这类工作列为&quot;未来的基准中心研究可以补的小型实证扩展&quot;。</p><p>这意味着一个循环风险：论文用指标有效性未被确立来批评现有比较，而它自己关于哪些指标更可信的建议同样缺少直接证据。作者对此是自觉的（IX-D 列了三条威胁：偏向公开可比较的研究、对 2025–2026 年工作的时效性风险、主张的指标依赖性），并把若干 2026 年新工作称为 frontier signals rather than settled consensus。</p><p>另有一处<strong>平凡基线</strong>问题值得替这篇综述说得更重。论文引用了 &quot;Is Ego Status All You Need?&quot; 与 Hidden Biases，指出开环协议会奖励依赖自车状态的捷径、基准协议会扭曲结论——这实际上就是&quot;平凡基线能在开环指标上拿高分&quot;的问题。但论文在推荐报告协议（VII-D）时列了五组证据、十几项元信息，<strong>却没有把&quot;报告平凡基线&quot;写成一项硬性要求</strong>：比如恒速外推、只用自车状态的回归器、以及在闭环里&quot;原地不动/保守刹停&quot;这类退化策略在各指标上的得分。这类参照是判断一个指标是否可被平凡策略刷高的最直接手段，成本近乎为零，而它的缺席使 VII-D 的清单在&quot;指标有效性&quot;这一最核心的关切上留了口子（<strong>这是我对该清单的评估，不是论文的表述</strong>）。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周量级、不需要训练任何驾驶模型，就能对本文最核心的规范性主张做第一步检验。</p><ul><li><strong>数据</strong>：不采集新数据。选取一个公开的非反应式真日志基准（NAVSIM 类）与一个反应式闭环基准（Bench2Drive 类）各自的公开榜单/基线结果，取两者<strong>共同出现</strong>的方法集合。</li><li><strong>实现</strong>：为每个基准实现三个平凡参照——(a) 恒速外推（沿当前航向匀速）；(b) 只用自车状态（速度、加速度、航向角速率、路线指令）的小型回归器，不接任何感知输入；(c) 闭环里的&quot;保守策略&quot;（缓慢跟随路线，遇障即停）。</li><li><strong>测量</strong>：三个平凡参照在两个基准的主指标（PDMS / Driving Score）与各子指标上的得分；以及共同方法集合在两个基准上的<strong>排名相关性</strong>（Spearman）。</li><li><strong>判据</strong>：若 (b) 在真日志代理协议的主指标上达到公开方法中位数量级，则该协议的判别力主要来自感知之外的东西，本文&quot;NAVSIM 类分数是 proxy evidence 而非闭环替代&quot;的说法得到直接支持；若排名相关性显著低于 1 且倒置发生在头部方法之间，则&quot;不指明协议不得称 SOTA&quot;从建议升级为必要条件。两个结果都能把论文当前依赖二手引用的核心论断变成可复现的一手证据。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>站在反对者立场，最强的攻击是指出四轴分类学可能<strong>没有判别力</strong>：如果几乎所有 2024 年后的方法在四轴上都落在相同格子里（多视图或 BEV 输入、轨迹输出、BC 加辅助损失监督、开环加某个闭环基准），那这套分类学就只是把文献重新排了个序。</p><p>具体实验：对论文 Table III 里列出的全部代表性方法做<strong>分类学的信息量测量</strong>——统计四轴各选项的边缘分布与联合分布熵，再计算&quot;四轴取值&quot;对一组外部结果变量（闭环 driving score 分档、是否公开可复现、报告的推理延迟分档）的互信息。</p><ul><li>如果四轴取值对结果变量几乎没有互信息，那么这套分类学是描述性的而非预测性的，论文&quot;两个骨干不同的方法可能属于同一规划族、两个 transformer 系统可能在解不同问题&quot;这一核心卖点就缺少经验支撑。</li><li>如果<strong>评测协议</strong>这一轴的互信息显著高于其余三轴，那反而<strong>强化</strong>了论文的中心论点，并给出一个更锋利的版本：不是&quot;四轴同等重要&quot;，而是&quot;评测协议这一轴主导了主张的可信度，其余三轴主要影响机制解释&quot;。</li></ul><p>另一条<strong>可预测的失效路径</strong>：论文在 VIII-D 里指出算力常被少报，而在线语言推理正是算力开销最大的一种用法。可以推断，在<strong>算力归一化</strong>的比较下，很多在线 VLM 规划的收益会被同等算力下更大的纯视觉规划器抹平（论文提到 DiMA 走蒸馏、DrivoR 用 register token 压缩、WAM-Flow 做并行解码，正是朝这个方向）。证伪实验很直接：把若干 VLA 驾驶方法与纯视觉基线放在<strong>相同延迟预算</strong>下重测闭环指标；若优势在延迟归一化后消失，“语言改善规划”就该限定成“训练时语言监督改善规划”。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动它的局限</strong>：本文把指标有效性诊断为最核心的未解问题（Table XIII 第一行），给出的方向是跨基准相关性与指标失效的因果分析。但相关性研究只能告诉你两个既有指标一致或不一致，无法告诉你<strong>哪一个更接近真实的驾驶安全</strong>，因为缺少 ground truth。</p><p><strong>换一个 framing</strong>：把指标当成<strong>待校准的检测器</strong>来处理。给定一批带真实结果标签的驾驶事件（真实路测中发生的碰撞、接管、违规），把每个候选指标视为对这段行为是否不安全的预测器，像评价诊断测试那样报告它的敏感度、特异度、校准曲线与不同基础率下的阳性预测值。区别在于：<strong>指标从评分工具变成需要先被验证的测量仪器</strong>，而验证需要外部标签，不能靠指标互相比较完成。</p><p><strong>可借鉴的相邻工具</strong>：临床诊断测试评价体系（ROC / 校准 / 决策曲线分析），以及软件工程里的<strong>变异测试</strong>（mutation testing）——后者提供了在缺少真实缺陷时构造已知缺陷的成熟做法，正好对应驾驶里&quot;注入已知不安全行为&quot;的需求。本文引用的 Fail2Drive 那类配对闭环泛化基准是很好的注入起点。</p><p><strong>第一个实验长什么样</strong>：从一个强基线出发注入受控缺陷，构造一组<strong>已知不安全</strong>的策略变体——最小车距缩小固定比例、红灯响应延迟固定帧数、关闭不确定场景下的减速，每种缺陷设多个强度档，于是不安全程度是已知的。让全部候选指标（ADE、FDE、PDMS、Driving Score、RFS 及各类子指标）对这些变体打分，测量每个指标的<strong>缺陷强度-分数单调性</strong>与<strong>最小可检出缺陷强度</strong>。一个连“红灯延迟两帧”都测不出来的指标，无论与别的指标相关性多高，都不该被当作安全证据。这个实验不需要新模型、也不需要真实路测标签，却能第一次给出“指标能检出什么”的定量答案——正是本文列为头号开放问题、却只能建议做相关性研究的那一块。</p>',56)])])}const c=n(a,[["render",s]]);export{h as __pageData,c as default};
